import{_ as e,o,c as r,a3 as s}from"./chunks/framework.Ba39LDvt.js";const h=JSON.parse('{"title":"站点维护","description":"本站的构建、发布、分支保护与依赖更新流程。","frontmatter":{"title":"站点维护","description":"本站的构建、发布、分支保护与依赖更新流程。"},"headers":[],"relativePath":"about/maintenance.md","filePath":"about/maintenance.md","lastUpdated":1795525517000}'),a={name:"about/maintenance.md"};function d(n,t,i,c,g,l){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="站点维护" tabindex="-1">站点维护 <a class="header-anchor" href="#站点维护" aria-label="Permalink to &quot;站点维护&quot;">​</a></h1><p>维护者通过 Pull Request（合并请求）审阅内容和配置。合并到 <code>main</code> 后，GitHub Actions 用 Node.js 和 VitePress 生成静态 HTML，并将 <code>docs/.vitepress/dist/</code> 交给 GitHub Pages 发布。每次构建都从仓库中的 Markdown、<code>package.json</code> 与 <code>package-lock.json</code> 开始。</p><h2 id="站点由什么组成" tabindex="-1">站点由什么组成 <a class="header-anchor" href="#站点由什么组成" aria-label="Permalink to &quot;站点由什么组成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>作用</th></tr></thead><tbody><tr><td><code>docs/.vitepress/config.mts</code></td><td>站点标题、顶部导航、侧边栏、本地搜索、编辑链接、Markdown 与 Mermaid 配置</td></tr><tr><td><code>docs/.vitepress/data/</code></td><td>教授（<code>faculty.ts</code>）、课程（<code>courses.ts</code>）与方向（<code>directions.ts</code>）的唯一数据源</td></tr><tr><td><code>docs/.vitepress/theme/</code></td><td>配色与全局组件：首页、方向拓扑图、教授卡片、课程表</td></tr><tr><td><code>.github/workflows/ci.yml</code></td><td>PR 检查 <strong>Documentation CI / docs-build</strong>，以只读权限运行 <code>npm run build</code></td></tr><tr><td><code>.github/workflows/deploy.yml</code></td><td>合并到 <code>main</code> 后构建并部署到 GitHub Pages</td></tr></tbody></table><p>中文全文搜索由 VitePress 的本地索引在构建期生成，不依赖外部服务。LaTeX 公式由 <code>markdown-it-mathjax3</code> 在构建期排版为 SVG；Mermaid 图由 <code>vitepress-plugin-mermaid</code> 打包进站点，在读者打开含图页面时渲染。升级依赖后可用<a href="/shanghaitech-ic-wiki-dev.github.io/about/writing">文章写作示例</a>验证这些功能。</p><h2 id="首次发布与重新部署" tabindex="-1">首次发布与重新部署 <a class="header-anchor" href="#首次发布与重新部署" aria-label="Permalink to &quot;首次发布与重新部署&quot;">​</a></h2><ol><li>打开仓库 <strong>Settings → Pages → Build and deployment</strong>，在 <strong>Source</strong> 选择 <strong>GitHub Actions</strong>。仓库已经提供部署工作流。<a href="https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site" target="_blank" rel="noreferrer">GitHub Pages 发布源说明</a></li><li>在 PR 的 <strong>Checks</strong> 查看 <strong>Documentation CI / docs-build</strong>。构建通过后，维护者检查引用、版权和导航，再按仓库审核规则合并。</li><li>合并后打开 <strong>Actions → Deploy to GitHub Pages</strong>，选择与合并提交相符的运行。先确认 <strong>build</strong> 成功上传静态文件，再确认 <strong>deploy</strong> 成功。在运行摘要中打开 <strong>github-pages</strong> 环境显示的网址，点开一个板块，搜索一个中文词，确认当前版本可用。<a href="https://docs.github.com/en/pages/getting-started-with-github-pages/using-custom-workflows-with-github-pages" target="_blank" rel="noreferrer">GitHub Pages 自定义工作流</a></li><li>需要从当前正式版本重新发布时，在同一工作流选择 <strong>Run workflow</strong>，将分支选为 <strong>main</strong>。如果本次修改需要回退，通过新的 PR 撤销相关提交，合并后会自动部署。</li></ol><p>构建失败时，展开第一个红色步骤。<code>npm ci</code> 失败通常是 <code>package.json</code> 与 <code>package-lock.json</code> 不一致，在本地重新 <code>npm install</code> 并提交更新后的锁文件。VitePress 报告的死链会指出源文件与目标路径，可在本地用 <code>npm run build</code> 复现。读取 Pages 配置失败时，先核对发布源。部署被挂起时，检查 <strong>Settings → Environments → github-pages</strong> 中已有的分支限制或审批要求。</p><h2 id="保护-main-分支" tabindex="-1">保护 main 分支 <a class="header-anchor" href="#保护-main-分支" aria-label="Permalink to &quot;保护 main 分支&quot;">​</a></h2><p>首次部署和 PR 检查成功后，建议由仓库管理员进入 <strong>Settings → Rules → Rulesets → New ruleset → New branch ruleset</strong>，将名称设为 <code>protect-main</code>，<strong>Enforcement status</strong> 选 <strong>Active</strong>。在 <strong>Target branches → Add target</strong> 添加匹配 <code>main</code> 的规则，再保存下列选项。<a href="https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/creating-rulesets-for-a-repository" target="_blank" rel="noreferrer">GitHub Rulesets 创建说明</a></p><table tabindex="0"><thead><tr><th>选项</th><th>建议设置与效果</th></tr></thead><tbody><tr><td>Require a pull request before merging</td><td>审批数设为 <strong>1</strong>，由另一位有审核权限的维护者批准。</td></tr><tr><td>Require status checks to pass</td><td>添加 GitHub Actions 产生的 <strong>docs-build</strong>。如果列表里还找不到，先让一个面向 <code>main</code> 的 PR 成功跑完 CI。</td></tr><tr><td>Block force pushes</td><td>勾选，阻止强制推送改写正式分支历史。</td></tr><tr><td>Restrict deletions</td><td>勾选，保护正式分支免于删除。</td></tr></tbody></table><p>规则建议只应用于本仓库。保存后，可在下一份内容 PR 中核对未通过审核时的合并按钮状态，以及 <strong>Checks</strong> 中的构建结果。<a href="https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-rulesets/available-rules-for-rulesets" target="_blank" rel="noreferrer">GitHub 分支规则选项</a></p><h2 id="更新依赖" tabindex="-1">更新依赖 <a class="header-anchor" href="#更新依赖" aria-label="Permalink to &quot;更新依赖&quot;">​</a></h2><p>依赖版本记录在 <code>package-lock.json</code> 中。升级时在独立分支运行 <code>npm install -D 包名@版本</code>，再执行 <code>npm run build</code> 与 <code>npm run preview</code>，回归检查首页拓扑图、中文搜索、一张 Mermaid 图、写作示例中的公式以及手机宽度下的导航。<code>vitepress-plugin-mermaid</code> 声明了它支持的 Mermaid 主版本，升级 Mermaid 前先核对插件的兼容范围。</p><p>更新 Actions 时，两个工作流中的 <code>uses</code> 指向官方发布对应的完整提交 SHA，后面的注释记录版本号。</p><p>如果将来更改组织名或仓库名，更新 <code>docs/.vitepress/config.mts</code> 中的仓库地址（编辑链接与社交链接）、README 的访问入口，并核对 GitHub Pages 的发布源。发布后从首页进入一篇文章，确认搜索、编辑入口和分享出去的网址均指向新站。</p>',16)])])}const p=e(a,[["render",d]]);export{h as __pageData,p as default};
